38	const PROCESSING_FEE = 5;
39	
40	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
41	
42	/** Rounds up in the MHPCO's favor, ignoring binary floating-point noise. */
43	const roundPremium = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
44	
45	const BASE_PREMIUMS: Record<string, number> = {
46	  sword: 100,
47	  amulet: 60,
48	  staff: 80,
49	  potion: 40,
50	};
51	
52	const quotePremium = (items: Item[]): number => {
53	  const basePremium = items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
54	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
55	  return roundPremium(basePremium + firstInsuranceSurcharge + PROCESSING_FEE);
56	};
57	
58	const runStep = (step: Step): Result => {
59	  if (step.op === "quote") return { premium: quotePremium(step.items) };
60	  throw new Error(`Unsupported step: ${step.op}`);
61	};
62	
63	export const runScenario = (scenario: Scenario): { results: Result[] } => {
64	  return { results: scenario.steps.map(runStep) };
65	};
